const KEY='claro-facturas-v1';let db;let legacyPresent=false;let storageOK=true;try{const raw=session.user.isRoot&&emitter.isOriginal?localStorage.getItem(KEY):null;legacyPresent=!!raw;db=raw?JSON.parse(raw):seed();if(!db?.invoices||!db?.clients||!db?.company)throw Error();}catch{db=seed();storageOK=false;}
