localDatabase.onNotice=message=>toast(message);
localDatabase.onError=e=>{storageOK=false;storageErrorMessage=e.message;toast(e.message);let banner=document.querySelector('#database-error');if(!banner){banner=document.createElement('div');banner.id='database-error';banner.className='error';banner.setAttribute('role','alert');document.querySelector('.content')?.prepend(banner);}banner.replaceChildren();const message=document.createElement('p');message.textContent=e.message;banner.append(message);const backup=document.createElement('button');backup.className='btn';backup.dataset.action='backup';backup.textContent='Descargar cambios sin guardar';banner.append(backup);const status=document.querySelector('.save-status');if(status)status.textContent='Cambios sin guardar';};
